458	// Loop 3: poll GitHub for new issues. Issues labelled benana:auto start a run automatically.
459	function startPolling() {
460	  clearInterval(pollTimer);
461	  const tick = async () => {
462	    if (!ctx) return;
463	    const owner = ctx;
464	    try {
465	      const issues = await github.openIssues(owner.repo);
466	      if (ctx !== owner) return;
467	      for (const i of issues) {
468	        if (inbox.has(i.number)) continue;
469	        const auto = i.labels.some((l) => l.name === 'benana:auto');
470	        inbox.set(i.number, { number: i.number, title: i.title, body: (i.body || '').slice(0, 2000), url: i.html_url, labels: i.labels.map((l) => l.name), auto, state: 'new', at: Date.parse(i.created_at) });
471	        if (auto && ctx.repoPath) {
