609	// its title ("Minecraft 1.21.4 - Multiplayer ..."), never another window.
610	function captureMinecraft() {
611	  const title = new RegExp(`^Minecraft\\*? ${game.VERSION.replace(/\./g, '\\.')}(?![\\d.])`);
612	  session.defaultSession.setDisplayMediaRequestHandler(async (_request, callback) => {
613	    try {
614	      const sources = await desktopCapturer.getSources({ types: ['window'], thumbnailSize: { width: 0, height: 0 } });
615	      // The user's own client ("Play in Minecraft") has the same title, so prefer the camera's window handle.
616	      const hwnd = game.status().cameraWindow;
617	      const source = (hwnd && sources.find((s) => s.id.split(':')[1] === String(hwnd))) || sources.find((s) => title.test(s.name));
618	      callback(source ? { video: source } : {});
619	    } catch {
620	      callback({});
621	    }
622	  });
623	}
