import React from "react";
import { call, on } from "../../api.js";
import { Markdown } from "./BuildPage.jsx";
import { Empty, PageHead, ROLE, SectionHead, Status, TraceButton, fmtMoney } from "./shared.jsx";
import "./cfo.css";

// Creator CFO: what each mod cost to make (from the agents' recorded usage), what the next one will cost, and a CFO
// that answers with the creator's cfo.ai model over its MCP server, and writes back to it when asked.

const pct = (n) => (n == null ? "—" : `${Math.round(n * 100)}%`);
const money = (n) => (n == null ? "—" : n > 0 && n < 0.01 ? "<$0.01" : fmtMoney(n));

// Questions that need cfo.ai: the creator's own plan, scenarios, alerts and a model that keeps the numbers.
function suggestions(b) {
  const t = b?.totals;
  const top = b?.mods.find((m) => m.status === "passed" && m.cost > 0 && !m.remix);
  return [
    { label: "Sync my build costs", q: "Record my Benana build costs in cfo.ai as a Benana table (one row per mod: build cost, rework, attempts, status) so they stay in my model." },
    top && { label: `Price ${top.name}`, q: `What should I charge for ${top.name} on the Benana marketplace? It cost ${money(top.cost)} to build in ${top.attempts} attempt${top.attempts === 1 ? "" : "s"}. Use my cfo.ai plan's margins and tell me the break-even.` },
    t && { label: "10 mods a month?", q: `Build a Benana scenario in cfo.ai: if I ship 10 mods a month at my current ${money(t.costPerVerifiedMod)} per verified mod, what is my monthly build spend, and how many $1.99 sales a month cover it?` },
    t?.reworkShare > 0.05 && { label: "Cost of rework", q: `${pct(t.reworkShare)} of my build spend (${money(t.rework)}) went to fix attempts. What does that cost me per year at my current pace, and is it worth cutting?` },
    { label: "Alert me on overspend", q: "Set up a weekly Benana alert in cfo.ai that warns me if my cost per verified mod goes above $1.00." },
  ].filter(Boolean);
}

export default function CfoPage({ mods }) {
  const [books, setBooks] = React.useState(null);
  const [cfo, setCfo] = React.useState(null);
  const [error, setError] = React.useState("");
  const [question, setQuestion] = React.useState("");
  const [live, setLive] = React.useState(null); // { id, question, events, entry? }
  const [history, setHistory] = React.useState([]);
  const [exported, setExported] = React.useState(null);
  const askRef = React.useRef(null);
  const version = mods.map((m) => `${m.id}:${m.updatedAt || 0}`).join(",");

  React.useEffect(() => {
    call("cfo:books").then(setBooks).catch((e) => setError(e.message));
  }, [version]);

  const check = React.useCallback(() => {
    setCfo((c) => ({ ...(c || {}), checking: true }));
    call("cfo:status").then(setCfo).catch((e) => setCfo({ state: "failed", detail: e.message }));
  }, []);

  React.useEffect(() => {
    check();
    call("cfo:history").then(setHistory).catch(() => {});
    return on("cfo:event", (ev) => {
      if (ev.kind === "start") setLive({ id: ev.askId, question: ev.question, events: [] });
      else if (ev.kind === "done") {
        setLive((l) => (l?.id === ev.askId ? { ...l, entry: ev.entry } : l));
        setHistory((h) => [ev.entry, ...h.filter((x) => x.id !== ev.entry.id)]);
      } else setLive((l) => (l?.id === ev.askId ? { ...l, events: [...l.events, ev].slice(-40) } : l));
    });
  }, [check]);

  const asking = Boolean(live && !live.entry);
  const ask = (q = question) => {
    const text = q.trim();
    if (!text || asking) return;
    setError("");
    setQuestion("");
    setLive({ id: null, question: text, events: [] });
    call("cfo:ask", { question: text }).catch((e) => { setError(e.message); setLive(null); });
  };
  const prefill = (q) => {
    setQuestion(q);
    askRef.current?.scrollIntoView({ behavior: "smooth", block: "start" });
    askRef.current?.querySelector("textarea")?.focus();
  };

  const t = books?.totals;
  return (
    <div className="view cfo-page">
      <PageHead
        eyebrow="Creator finance · powered by cfo.ai"
        title="CFO"
        sub="What your mods cost to make, what to charge for them, and what the next one will cost. Benana records every agent's spend; cfo.ai turns it into a plan."
      >
        <CfoBadge cfo={cfo} />
      </PageHead>
      {error && <div className="alert">{error}</div>}

      <section className="kpis">
        <Kpi label="Spent on agents" value={money(t?.spend)} sub={t ? `${t.mods} mods · ${t.passed} verified` : ""} />
        <Kpi label="Cost per verified mod" value={money(t?.costPerVerifiedMod)} sub={t ? `includes ${money(t.failedSpend)} on mods that never passed` : ""} />
        <Kpi label="Spent on rework" value={pct(t?.reworkShare)} sub={t ? `${money(t.rework)} on fix attempts` : ""} tone={t?.reworkShare > 0.2 ? "warn" : ""} />
        <Kpi label="Passed first try" value={pct(t?.firstTryRate)} sub={t?.remixes ? `remixes started at ${money(t.remixMedianCost)} vs ${money(t.scratchMedianCost)} from scratch` : "of finished mods"} />
      </section>

      <div className="cfo-grid">
        <section className="panel pad cfo-ask" ref={askRef}>
          <SectionHead title="Ask your CFO">
            <span className="cfo-src cfo">cfo.ai MCP</span>
          </SectionHead>
          <p className="meta">Answers come from your cfo.ai model plus Benana's real build costs. When you ask it to record, model or alert, it writes to cfo.ai, so the plan keeps up with what you build.</p>
          {cfo && cfo.state !== "connected" && !cfo.checking && <ConnectSteps cfo={cfo} onChange={setCfo} onCheck={check} />}
          <div className="cfo-chips">
            {suggestions(books).map((s) => (
              <button key={s.label} className="cfo-chip" disabled={asking} onClick={() => prefill(s.q)} title={s.q}>{s.label}</button>
            ))}
          </div>
          <form className="cfo-input" onSubmit={(e) => { e.preventDefault(); ask(); }}>
            <textarea
              rows={2}
              value={question}
              onChange={(e) => setQuestion(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); ask(); } }}
              placeholder="Ask about pricing, budgets, runway, or what to build next"
              disabled={asking}
            />
            {asking ? (
              <button type="button" className="btn danger" onClick={() => call("cfo:stop")}>Stop</button>
            ) : (
              <button className="btn solid" disabled={!question.trim()}>Ask</button>
            )}
          </form>
          {live && <Answer live={live} />}
          {history.filter((h) => h.id !== live?.id).length > 0 && (
            <details className="cfo-history">
              <summary>Earlier answers ({history.filter((h) => h.id !== live?.id).length})</summary>
              {history.filter((h) => h.id !== live?.id).map((h) => (
                <details key={h.id} className="cfo-past">
                  <summary>{h.question}</summary>
                  <Answer live={{ question: h.question, events: [], entry: h }} compact />
                </details>
              ))}
            </details>
          )}
        </section>

        <Quote onAsk={prefill} />
      </div>

      <section className="panel cfo-books">
        <div className="panel-head">
          <SectionHead title="Per-mod books" count={books?.mods.length}>
            <div className="cfo-actions">
              <button className="btn sm" onClick={() => call("cfo:export").then(setExported).catch((e) => setError(e.message))}>Export CSV for cfo.ai</button>
              {exported && <button className="btn sm" onClick={() => call("open-path", exported.dir)}>Show file ({exported.rows} rows)</button>}
            </div>
          </SectionHead>
        </div>
        {!books ? <Empty>Loading…</Empty> : !books.mods.length ? <Empty>Build a mod and its costs appear here.</Empty> : (
          <table className="table">
            <thead>
              <tr>
                <th>Mod</th><th>Status</th><th className="num">Attempts</th><th className="num">Build cost</th><th className="num">Rework</th><th className="num">Pays back at $1.99</th><th />
              </tr>
            </thead>
            <tbody>
              {books.mods.map((m) => (
                <tr key={m.id}>
                  <td><strong className="cfo-mod">{m.name}</strong>{m.remix && <span className="cfo-tag">remix{m.remixOf ? ` of ${m.remixOf}` : ""}</span>}</td>
                  <td><Status status={m.status} /></td>
                  <td className="num">{m.attempts}</td>
                  <td className="num">{money(m.cost)}</td>
                  <td className="num">{m.rework ? money(m.rework) : "—"}</td>
                  <td className="num">{m.cost ? `${m.breakEven[1].sales} sale${m.breakEven[1].sales === 1 ? "" : "s"}` : "free"}</td>
                  <td className="num">
                    {m.status === "passed" && (
                      <button className="btn sm" disabled={asking} onClick={() => prefill(`What should I charge for ${m.name} on the Benana marketplace? It cost ${money(m.cost)} to build in ${m.attempts} attempt${m.attempts === 1 ? "" : "s"}${m.rework ? `, ${money(m.rework)} of it on fixes` : ""}. Use my cfo.ai plan's margins and tell me the break-even.`)}>
                        Price it
                      </button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </section>

      {t && <SpendByRole byRole={t.byRole} byModel={t.byModel} />}
      <p className="meta cfo-foot">Build costs are the API cost Claude Code reported for each agent session, read from your local mod records. Remixes start from a published mod, so their first build costs nothing.</p>
    </div>
  );
}

function Kpi({ label, value, sub, tone }) {
  return (
    <div className={`kpi ${tone || ""}`}>
      <span>{label}</span>
      <strong>{value}</strong>
      <small>{sub}</small>
    </div>
  );
}

function CfoBadge({ cfo }) {
  const state = cfo?.checking ? "checking" : cfo?.state;
  const label = { connected: "cfo.ai connected", "needs-auth": "cfo.ai: sign in needed", "not-added": "cfo.ai not connected", failed: "cfo.ai unreachable", checking: "Checking cfo.ai…", "no-claude": "Claude Code missing" }[state] || "cfo.ai";
  return (
    <span className={`cfo-badge ${state === "connected" ? "ok" : ""}`} title={cfo?.detail || ""}>
      <i />{label}
    </span>
  );
}

function ConnectSteps({ cfo, onChange, onCheck }) {
  const [busy, setBusy] = React.useState(false);
  const [err, setErr] = React.useState("");
  const run = (channel) => {
    setBusy(true);
    setErr("");
    call(channel).then((r) => { if (r?.state) onChange(r); }).catch((e) => setErr(e.message)).finally(() => setBusy(false));
  };
  return (
    <div className="cfo-connect">
      <strong>Connect cfo.ai to see this work on your own plan</strong>
      <ol>
        <li className={cfo.added ? "done" : ""}>
          Add the cfo.ai MCP server to Claude Code.
          {!cfo.added && <button className="btn sm" disabled={busy} onClick={() => run("cfo:connect")}>Add cfo.ai</button>}
        </li>
        <li>
          Sign in: a terminal opens on <code>/mcp</code>. Pick <code>cfoai</code>, choose Authenticate, and approve in the browser.
          <button className="btn sm" disabled={busy || !cfo.added} onClick={() => run("cfo:signin")}>Open sign-in</button>
        </li>
        <li>
          Come back and check the connection.
          <button className="btn sm" disabled={busy} onClick={onCheck}>Check</button>
        </li>
      </ol>
      <small>No cfo.ai account? Sign up at <button className="cfo-link" onClick={() => window.benana?.openExternal("https://cfo.ai/neathacks")}>cfo.ai/neathacks</button>. You can still ask now; answers use Benana's numbers only until cfo.ai is connected.</small>
      {err && <small className="bad">{err}</small>}
    </div>
  );
}

function Answer({ live, compact }) {
  const { entry } = live;
  const calls = (entry?.tools?.length ? entry.tools : live.events.filter((e) => e.kind === "tool").map((e) => ({ name: e.name, cfo: e.cfo })));
  const cfoCalls = calls.filter((c) => c.cfo);
  const thinking = live.events.filter((e) => e.kind === "text").at(-1)?.text;
  return (
    <div className={`cfo-answer ${compact ? "compact" : ""}`}>
      {!compact && <p className="cfo-q">{live.question}</p>}
      {calls.length > 0 && (
        <ol className="cfo-calls">
          {calls.map((c, i) => (
            <li key={i} className={c.cfo ? "cfo" : ""}>
              <span>{c.cfo ? "cfo.ai" : "Benana"}</span>{c.cfo ? c.name : c.name === "Read" ? "read build costs" : c.name}
            </li>
          ))}
        </ol>
      )}
      {!entry && <p className="cfo-working"><i />{thinking ? thinking.slice(0, 220) : cfoCalls.length ? "Working in cfo.ai…" : "Reading your books…"}</p>}
      {entry?.answer && <Markdown text={entry.answer} />}
      {entry?.error && !entry.answer && <p className="bad">{entry.error}</p>}
      {entry && (
        <div className="cfo-answer-foot">
          <span>{cfoCalls.length ? `${cfoCalls.length} cfo.ai call${cfoCalls.length === 1 ? "" : "s"}` : "No cfo.ai calls"}</span>
          {entry.usage?.costUsd != null && <span>this answer cost {money(entry.usage.costUsd)}</span>}
          <TraceButton sessionId={entry.sessionId} />
        </div>
      )}
    </div>
  );
}

// A quote before building, from the creator's own most similar past mods.
function Quote({ onAsk }) {
  const [prompt, setPrompt] = React.useState("");
  const [q, setQ] = React.useState(null);
  const [err, setErr] = React.useState("");
  const run = (e) => {
    e?.preventDefault();
    if (!prompt.trim()) return;
    setErr("");
    call("cfo:quote", { prompt }).then((r) => (r.ok ? setQ({ ...r, prompt }) : setErr(r.error))).catch((x) => setErr(x.message));
  };
  return (
    <section className="panel pad cfo-quote">
      <SectionHead title="Quote a mod before you build it" />
      <p className="meta">Describe the mod. The estimate comes from your most similar past builds, including how often they needed fixes.</p>
      <form onSubmit={run} className="cfo-input">
        <textarea rows={2} value={prompt} onChange={(e) => setPrompt(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter" && !e.shiftKey) run(e); }} placeholder="A trident that calls down lightning on hit" />
        <button className="btn solid" disabled={!prompt.trim()}>Quote</button>
      </form>
      {err && <p className="bad">{err}</p>}
      {q && (
        <div className="cfo-quote-out">
          <div className="cfo-quote-num">
            <strong>{money(q.expected)}</strong>
            <span>likely {money(q.low)} – {money(q.high)}</span>
          </div>
          <ul>
            {q.fixChance != null && <li><strong>{pct(q.fixChance)}</strong> of your mods needed a fix{q.costPerFix ? <>; each fix round cost about <strong>{money(q.costPerFix)}</strong></> : null}.</li>}
            <li>{q.matched ? "Based on" : "No close match yet, so based on all your builds:"} {q.basis.map((b) => `${b.name} (${money(b.cost)})`).join(", ")}</li>
          </ul>
          <button
            className="btn sm"
            onClick={() => onAsk(`I'm about to build this mod: "${q.prompt}". Benana quotes about ${money(q.expected)} to build (range ${money(q.low)}–${money(q.high)}, ${pct(q.fixChance)} chance it needs a fix). Given my cfo.ai plan, is it worth building, what price pays it back, and what budget should I set?`)}
          >
            Is it worth it? Ask cfo.ai
          </button>
        </div>
      )}
    </section>
  );
}

function SpendByRole({ byRole, byModel }) {
  const roles = Object.entries(byRole).sort((a, b) => b[1] - a[1]);
  const total = roles.reduce((n, [, v]) => n + v, 0) || 1;
  return (
    <section className="panel pad cfo-roles">
      <SectionHead title="Where the money goes">
        <span className="meta">{Object.entries(byModel).map(([m, v]) => `${m} ${money(v)}`).join(" · ")}</span>
      </SectionHead>
      <div className="cfo-bar">
        {roles.map(([role, v]) => <i key={role} className={`r-${role}`} style={{ flexGrow: v }} title={`${ROLE[role] || role}: ${money(v)}`} />)}
      </div>
      <ul className="cfo-legend">
        {roles.map(([role, v]) => (
          <li key={role}><i className={`r-${role}`} />{ROLE[role] || role}<strong>{money(v)}</strong><span>{pct(v / total)}</span></li>
        ))}
      </ul>
    </section>
  );
}

