export const ROLE = {
  spec: "Spec agent",
  builder: "Builder",
  fixer: "Fixer",
  playtester: "Playtester",
  grader: "Grader",
  coach: "Coach",
  benana: "Benana",
  seeded: "Seeded fixture",
};

const STATUS = {
  queued: "Queued",
  running: "Running",
  passed: "Passed",
  failed: "Failed",
  stopped: "Stopped",
  pass: "Pass",
  fail: "Fail",
  blocked: "Blocked",
  pending: "Not run",
};

export function Status({ status, children }) {
  return (
    <span className={`status ${status}`}>
      <i />
      {children || STATUS[status] || status}
    </span>
  );
}

.studio .kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--panel);
  overflow: hidden;
}
.studio .kpis.three {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.studio .kpi {
  display: grid;
  gap: 2px;
  min-width: 0;
  padding: 18px 20px 17px;
}
.studio .kpi + .kpi {
  border-left: 1px solid var(--line);
}
.studio .kpi span {
  color: var(--text-2);
  font-size: 12px;
}
.studio .kpi strong {
  margin-top: 4px;
  color: var(--text);
  font-size: 30px;
  font-weight: 600;
  letter-spacing: -0.035em;
  line-height: 1.15;
  font-variant-numeric: tabular-nums;
}
.studio .insight-hero {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(260px, 0.82fr);
  gap: 16px;
}
  --text: #f2f0e9;
  --text-2: #aaaeb7;
  --text-3: #858b96;

input.content:
/* Creator CFO page. cfo.ai's own calls get their own color so it is clear which parts of an answer came from it. */
.studio .cfo-page {
  --cfo: #5ad1a0;
  --cfo-soft: rgba(90, 209, 160, 0.1);
}
.studio .cfo-page > * + * {
  margin-top: 16px;
}
.studio .cfo-page .kpi.warn strong {
  color: var(--warn);
}
.studio .cfo-page .bad {
  color: var(--bad-text);
  font-size: 12.5px;
}

.studio .cfo-badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 28px;
  padding: 0 11px;
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  color: var(--text-2);
  font-size: 12px;
}
.studio .cfo-badge i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--text-3);
}
.studio .cfo-badge.ok {
  border-color: rgba(90, 209, 160, 0.35);
  color: var(--cfo);
}
.studio .cfo-badge.ok i {
  background: var(--cfo);
  box-shadow: 0 0 0 3px var(--cfo-soft);
}

.studio .cfo-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.6fr) minmax(280px, 1fr);
  gap: 16px;
  align-items: start;
}
@media (max-width: 1250px) {
  .studio .cfo-grid {
    grid-template-columns: minmax(0, 1fr);
  }
}

.studio .cfo-src {
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 500;
}
.studio .cfo-src.cfo {
  background: var(--cfo-soft);
  color: var(--cfo);
}

.studio .cfo-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 12px 0 10px;
}
.studio .cfo-chip {
  height: 28px;
  padding: 0 11px;
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  background: transparent;
  color: var(--text-2);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}
.studio .cfo-chip:hover:not(:disabled) {
  border-color: rgba(90, 209, 160, 0.4);
  color: var(--text);
}
.studio .cfo-chip:disabled {
  opacity: 0.45;
}

.studio .cfo-input {
  display: flex;
  gap: 8px;
  align-items: flex-end;
}
.studio .cfo-input textarea {
  flex: 1;
  min-width: 0;
  padding: 9px 11px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background: var(--raised);
  color: var(--text);
  font: inherit;
  font-size: 13px;
  line-height: 1.45;
  resize: vertical;
}
.studio .cfo-input textarea:focus {
  outline: none;
  border-color: rgba(255, 255, 255, 0.25);
}

.studio .cfo-connect {
  display: grid;
  gap: 8px;
  margin-top: 12px;
  padding: 12px 14px;
  border: 1px dashed rgba(90, 209, 160, 0.35);
  border-radius: 9px;
  background: var(--cfo-soft);
  font-size: 12.5px;
  color: var(--text-2);
}
.studio .cfo-connect strong {
  color: var(--text);
}
.studio .cfo-connect ol {
  display: grid;
  gap: 7px;
  margin: 0;
  padding-left: 18px;
}
.studio .cfo-connect li .btn {
  margin-left: 8px;
}
.studio .cfo-connect li.done {
  color: var(--text-3);
  text-decoration: line-through;
}
.studio .cfo-connect small {
  color: var(--text-3);
}
.studio .cfo-link {
  padding: 0;
  border: 0;
  background: none;
  color: var(--cfo);
  font: inherit;
  cursor: pointer;
  text-decoration: underline;
}

.studio .cfo-answer {
  margin-top: 14px;
  padding: 14px 16px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--raised);
  font-size: 13px;
}
.studio .cfo-answer.compact {
  margin-top: 8px;
}
.studio .cfo-q {
  margin: 0 0 10px;
  color: var(--text);
  font-weight: 600;
}
.studio .cfo-calls {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin: 0 0 10px;
  padding: 0;
  list-style: none;
}
.studio .cfo-calls li {
  display: inline-flex;
  gap: 6px;
  align-items: center;
  padding: 3px 8px;
  border: 1px solid var(--line);
  border-radius: 6px;
  color: var(--text-2);
  font-family: var(--mono);
  font-size: 11px;
}
.studio .cfo-calls li span {
  color: var(--text-3);
  font-family: var(--sans);
}
.studio .cfo-calls li.cfo {
  border-color: rgba(90, 209, 160, 0.3);
  background: var(--cfo-soft);
  color: var(--text);
}
.studio .cfo-calls li.cfo span {
  color: var(--cfo);
  font-weight: 600;
}
.studio .cfo-working {
  display: flex;
  gap: 8px;
  align-items: center;
  margin: 0;
  color: var(--text-3);
}
.studio .cfo-working i {
  flex: none;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--cfo);
  animation: cfo-pulse 1.1s ease-in-out infinite;
}
@keyframes cfo-pulse {
  50% { opacity: 0.25; }
}
.studio .cfo-answer-foot {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px solid var(--line);
  color: var(--text-3);
  font-size: 11.5px;
}

.studio .cfo-history {
  margin-top: 12px;
  color: var(--text-3);
  font-size: 12px;
}
.studio .cfo-history summary,
.studio .cfo-past summary {
  cursor: pointer;
}
.studio .cfo-past {
  margin: 8px 0 0 12px;
  color: var(--text-2);
}

.studio .cfo-quote-out {
  margin-top: 14px;
}
.studio .cfo-quote-num {
  display: flex;
  gap: 10px;
  align-items: baseline;
}
.studio .cfo-quote-num strong {
  color: var(--text);
  font-size: 30px;
  font-weight: 600;
  letter-spacing: -0.035em;
}
.studio .cfo-quote-num span {
  color: var(--text-3);
  font-size: 12.5px;
}
.studio .cfo-quote-out ul {
  margin: 8px 0 12px;
  padding-left: 16px;
  color: var(--text-2);
  font-size: 12.5px;
  line-height: 1.55;
}
.studio .cfo-quote-out strong {
  color: var(--text);
}

.studio .cfo-actions {
  display: flex;
  gap: 6px;
}
.studio .cfo-mod {
  color: var(--text);
  font-weight: 600;
}
.studio .cfo-tag {
  margin-left: 8px;
  color: var(--entire);
  font-size: 11px;
}

.studio .cfo-bar {
  display: flex;
  gap: 2px;
  height: 10px;
  margin: 6px 0 12px;
  border-radius: 5px;
  overflow: hidden;
}
.studio .cfo-bar i {
  min-width: 3px;
}
.studio .cfo-legend {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));
  gap: 6px 18px;
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 12.5px;
  color: var(--text-2);
}
.studio .cfo-legend li {
  display: flex;
  gap: 8px;
  align-items: center;
}
.studio .cfo-legend li i {
  width: 8px;
  height: 8px;
  border-radius: 2px;
}
.studio .cfo-legend strong {
  margin-left: auto;
  color: var(--text);
  font-weight: 500;
  font-variant-numeric: tabular-nums;
}
.studio .cfo-legend span {
  width: 34px;
  color: var(--text-3);
  text-align: right;
}
.studio .cfo-page .r-spec { background: #8b93a7; }
.studio .cfo-page .r-builder { background: var(--accent); }
.studio .cfo-page .r-playtester { background: var(--neatlogs); }
.studio .cfo-page .r-fixer { background: var(--bad); }
.studio .cfo-page .r-grader { background: var(--entire); }
.studio .cfo-page .r-coach { background: var(--good); }

.studio .cfo-foot {
  margin-bottom: 8px;
}

